fn unique_suffix() -> String {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("the system clock should be after the Unix epoch")
        .as_nanos();
    let mut random_bytes = [0_u8; 8];
    getrandom::getrandom(&mut random_bytes).expect("the OS random source should be available");
    let random_suffix: String = random_bytes
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect();
    format!("{timestamp}-{random_suffix}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, suffix: &str) {
    let signing_key = SigningKey::from_bytes(&[13; 32]);
    let public_key = signing_key.verifying_key().to_bytes();
    let submission = EnrollmentSubmission {
        request_id: format!("administration-request-{suffix}"),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: format!("administration-node-{suffix}"),
        display_name: "Administration integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: public_key_fingerprint(&public_key),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id: submission.request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: submission.proposed_node_id.clone(),
        public_key_fingerprint: submission.public_key_fingerprint.clone(),
    };
    let now = SystemTime::now();
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("the test database should accept enrollment connections");
    enrollment
        .submit(&submission)
        .await
        .expect("the repository enrollment should be recorded");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: submission.public_key_fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "administration-integration-administrator".to_string(),
        })
        .await
        .expect("the repository enrollment should be approved");
    let nonce: [u8; 32] = Sha256::digest(suffix.as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, now)
        .await
        .expect("the approved repository should receive an activation challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("administration-receipt-{suffix}"),
            &format!("administration-signing-key-{suffix}"),
            now,
        )
        .await
        .expect("the repository enrollment should activate");
}

#[tokio::test]
async fn returns_an_honest_status_for_the_tenant_and_hides_it_from_another_tenant() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let suffix = unique_suffix();
    let tenant_id = format!("tenant-administration-{suffix}");
    let repository_id = format!("repository-administration-{suffix}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &suffix).await;

    let fleet = Arc::new(
        FleetStore::connect(&database_url)
            .await
            .expect("the test database should accept Fleet connections"),
    );
    let authorized = administration_routes(AdministrationApiState::new(
        fleet.clone(),
        Arc::from(tenant_id.clone()),
    ));
    let page_response = authorized
        .clone()
        .oneshot(
            Request::builder()
                .uri("/administration")
                .body(Body::empty())
                .expect("the Administration page request should build"),
        )
        .await
        .expect("the Administration page request should receive a response");
    assert_eq!(page_response.status(), StatusCode::OK);
    let page_body = to_bytes(page_response.into_body(), usize::MAX)
        .await
        .expect("the Administration page response should have a bounded body");
    let page = String::from_utf8(page_body.to_vec())
        .expect("the Administration page response should be UTF-8");
    assert!(page.contains("Administration"));
    assert!(!page.contains("DROP DATABASE"));

    let response = authorized
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/administration/status"
                ))
                .body(Body::empty())
                .expect("the authorized request should build"),
        )
        .await
        .expect("the authorized request should receive a response");
    assert_eq!(response.status(), StatusCode::OK);
    let body = to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("the Administration status response should have a bounded body");
    assert_eq!(
        serde_json::from_slice::<serde_json::Value>(&body)
            .expect("the Administration status response should be JSON"),
        json!({
            "repository_id": repository_id,
            "projection": {
                "freshness": "never_projected",
                "ledger_stream_position": 0,
                "projection_stream_position": null,
                "projection_updated_at_seconds": null,
            },
            "durability": {
                "state": "not_reported",
                "reason": "The deployment has not published a tenant-scoped durability report.",
            },
            "capabilities": [
                {"operation":"status_inspection","state":"available","reason":"Tenant-scoped projection and capability status are readable."},
                {"operation":"snapshot","state":"refused","reason":"A verified principal and adopted policy are required."},
                {"operation":"export","state":"refused","reason":"A verified principal, purpose, and redaction policy are required."},
                {"operation":"recovery_inspection","state":"unavailable","reason":"An identified backup artifact and recovery evidence are required."},
                {"operation":"lifecycle_purge","state":"refused","reason":"A verified principal, retention basis, and impact plan are required."},
            ],
        })
    );

    let foreign = administration_routes(AdministrationApiState::new(
        fleet,
        Arc::from(format!("foreign-{tenant_id}")),
    ));
    let foreign_response = foreign
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/administration/status"
                ))
                .body(Body::empty())
                .expect("the foreign request should build"),
        )
        .await
        .expect("the foreign request should receive a response");
    assert_eq!(foreign_response.status(), StatusCode::NOT_FOUND);
}
